WITH leaf_tasks AS (
  SELECT wi.work_item_id, wi.est_hours
  FROM work_items wi
  WHERE wi.engagement_id = (SELECT engagement_id FROM engagements WHERE code = :project_code LIMIT 1)
    AND NOT EXISTS (
      SELECT 1 FROM work_items child WHERE child.parent_item_id = wi.work_item_id
    )
)
SELECT CAST(COALESCE(SUM(est_hours), 0) AS REAL) AS total_leaf_est_hours
FROM leaf_tasks;
